# envcfg.py

import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env=None):
    if env is None:
        env = os.environ
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(toml_config)
        except FileNotFoundError:
            pass
    for key, value in env.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            env_value = _coerce_value(env_key, value, config)
            _set_nested_key(config, env_key, env_value)
    return config

def _coerce_value(key, value, config):
    default_value = _get_nested_key(config, key)
    if isinstance(default_value, int):
        return int(value)
    elif isinstance(default_value, float):
        return float(value)
    elif isinstance(default_value, bool):
        return value.lower() in ['true', '1', 'yes']
    elif isinstance(default_value, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for key {key}')

def _set_nested_key(d, key, value):
    keys = key.split('.')
    for k in keys[:-1]:
        if k not in d:
            d[k] = {}
        d = d[k]
    d[keys[-1]] = value

def _get_nested_key(d, key):
    keys = key.split('.')
    for k in keys:
        if k not in d:
            raise ConfigError(f'Missing key {key}')
        d = d[k]
    return d

# test_envcfg.py

import pytest
from envcfg import load_config, ConfigError

def test_precedence_order():
    defaults = {'a': 1, 'b': 2}
    toml_config = {'b': 3}
    env_config = {'APP_A': '4'}
    config = load_config(defaults, toml_path='config.toml', env_prefix='APP', env=env_config)
    assert config == {'a': 4, 'b': 3}

def test_nested_overrides():
    defaults = {'server': {'port': 8080}}
    toml_config = {'server': {'port': 8081}}
    env_config = {'APP_SERVER_PORT': '8082'}
    config = load_config(defaults, toml_path='config.toml', env_prefix='APP', env=env_config)
    assert config == {'server': {'port': 8082}}

def test_coercion_types():
    defaults = {'a': 1, 'b': 2.0, 'c': True, 'd': 'hello'}
    env_config = {'APP_A': '2', 'APP_B': '3.0', 'APP_C': 'false', 'APP_D': 'world'}
    config = load_config(defaults, env_prefix='APP', env=env_config)
    assert config == {'a': 2, 'b': 3.0, 'c': False, 'd': 'world'}

def test_error_cases():
    defaults = {'a': 1, 'b': 2.0, 'c': True, 'd': 'hello'}
    env_config = {'APP_A': 'two', 'APP_B': 'three', 'APP_C': 'yes', 'APP_D': '42'}
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP', env=env_config)

def test_missing_file():
    defaults = {'a': 1}
    config = load_config(defaults, toml_path='nonexistent.toml', env_prefix='APP')
    assert config == {'a': 1}

